package pe.ferresur.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import pe.ferresur.model.Rol; import pe.ferresur.repository.UsuarioRepository;
@Configuration public class SecurityConfig{
 @Bean public PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean public UserDetailsService userDetailsService(UsuarioRepository repo){return username->repo.findByUsernameIgnoreCase(username).filter(pe.ferresur.model.Usuario::isActivo).map(u->User.withUsername(u.getUsername()).password(u.getPassword()).roles(u.getRol()==Rol.ADMINISTRADOR?"ADMIN":"VENDEDOR").build()).orElseThrow(()->new UsernameNotFoundException("Usuario no encontrado o inactivo"));}
 @Bean public SecurityFilterChain filterChain(HttpSecurity http,RoleAwareSuccessHandler successHandler)throws Exception{http.authorizeHttpRequests(auth->auth.requestMatchers("/css/**","/js/**","/login","/registro","/error").permitAll().requestMatchers("/usuarios/**","/reportes/**","/sueldos/**").hasRole("ADMIN").requestMatchers("/productos/nuevo","/productos/editar/**","/productos/guardar","/productos/eliminar/**").hasRole("ADMIN").requestMatchers("/ventas/*/anular").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").loginProcessingUrl("/login").successHandler(successHandler).failureUrl("/login?error=true").permitAll()).logout(l->l.logoutUrl("/logout").logoutSuccessUrl("/login?logout=true").invalidateHttpSession(true).deleteCookies("JSESSIONID").permitAll()).csrf(c->c.ignoringRequestMatchers("/api/**"));return http.build();}
}
